import{_ as o,l as i,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"进程映像","description":"","frontmatter":{"title":"进程映像","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/process-image.md","filePath":"cs/process-image.md","lastUpdated":1789023840000}'),h={name:"cs/process-image.md"};function m(B,a,_,E,A,u){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="进程映像" tabindex="-1">进程映像 <a class="header-anchor" href="#进程映像" aria-label="Permalink to &quot;进程映像&quot;">​</a></h1><div class="epigraph"><p>进程是正在执行的程序；它不止是代码，还包括程序计数器、寄存器和变量。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems 整理</footer></div><p><a href="/cs/percpu">上一课</a>钉死内核拥有机器、用户态只能陷入。<a href="/cs/paging-vm">分页</a>已经给出每个地址空间自己的页表。缺口是：内核要在许多用户程序之间切换，还没有命名被切换的那一份<strong>状态包</strong>。本课把这份包叫做进程映像，不重讲页表怎么走。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>磁盘上的可执行文件是死的字节。<a href="/cs/load-dynlink">加载与动态链接</a>把它放进内存，但「正在跑」还需要：当前 PC 与通用寄存器、用户栈、堆、打开的文件、页表根。若只保存代码，切换回来时局部变量和文件偏移都丢了。缺口不是新的特权级，而是内核里一份可挂起、可恢复的映像。</p><p>本课不把线程从进程里拆开，那是下一课。这里默认一个进程一条执行流，映像与地址空间一一对应。</p><p><span class="marginnote">Unix 把进程控制块（PCB）做成内核对象：PID、状态、寄存器副本、内存描述、文件描述符表。映像是 PCB 加上它指向的用户页。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>映像至少含：用户地址空间（后课才画布局）、寄存器组、内核栈或陷入帧、资源表（文件、信号掩码稍后补）。创建进程是分配 PCB、建立页表、把程序装入；退出是回收这些。就绪、运行、阻塞是映像的三种调度可见状态，具体排队在调度课。</p>',9)),(e(),n(c,null,{default:r(()=>[d(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILE%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E6%96%87%E4%BB%B6%22%5D%20--%3E%20LOAD%5B%22%E8%A3%85%E5%85%A5%E7%94%A8%E6%88%B7%E9%A1%B5%22%5D%0A%20%20LOAD%20--%3E%20PCB%5B%22PCB%3A%20%E5%AF%84%E5%AD%98%E5%99%A8%E4%B8%8E%E8%B5%84%E6%BA%90%22%5D%0A%20%20PCB%20--%3E%20RUN%5B%22%E8%BF%90%E8%A1%8C%20%2F%20%E5%B0%B1%E7%BB%AA%20%2F%20%E9%98%BB%E5%A1%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>fork 与 exec 的细节、写时复制，都还没有；本课只要求「一份映像 = 一份可调度的用户状态」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内核切换时，当前映像的寄存器写入 PCB，页表根换成下一份，再恢复其寄存器。用户程序看不见这次保存；它只觉得自己一直在算。<a href="/cs/tlb-translate">TLB</a> 在换根之后必须失效或带地址空间标签，否则会用错页。本课不重导 TLB，只点明：换进程就是换映像，译址硬件跟着换。</p><p>文件偏移、工作目录属于映像而不是属于代码文件：同一程序跑两份，各有各的描述符表。这是后课管道两端各是一个进程的前提。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入轻量线程，不把容器与 cgroup 请进来，也不把进程树与会话写成 Unix 手册。僵尸与孤儿是实现细节，主干只承认「映像可以等子进程」。安全课的隔离会用同一对象，本课不讲沙箱策略。</p><p>内核栈与用户栈分开：陷入时硬件切栈，映像里两套指针都要保存。</p><p>后课默认：谈到「一个正在跑的程序」，它有 PCB 与用户地址空间。一个进程里如何出现多条执行流，下一课收。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核切换的对象是进程映像，不是磁盘上的二进制。</li><li>映像含寄存器、页表根、资源表；状态是运行、就绪、阻塞。</li><li>线程共享同一地址空间，是下一课的缺口。</li><li>出处：Tanenbaum and Bos, <em>MOS</em>；Silberschatz et al., <em>OSC</em> 进程概念。</li></ul>',10))])}const T=o(h,[["render",m]]);export{P as __pageData,T as default};
